{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Chain TVL Data",
    "url": "http://localhost:7802",
    "widgets_json": {
      "chains_table": {
        "name": "Top Chains by TVL",
        "description": "Current TVL of all chains from the desk aggregator.",
        "endpoint": "/chains-table",
        "type": "table",
        "w": 20,
        "h": 9,
        "params": [
          {
            "paramName": "chain",
            "type": "text",
            "label": "Chain",
            "value": "Ethereum",
            "description": "Chain the deck is focused on."
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "name",
                "headerName": "Chain",
                "cellDataType": "text"
              },
              {
                "field": "tvl_usd",
                "headerName": "TVL ($)",
                "cellDataType": "number",
                "formatterFn": "int"
              },
              {
                "field": "change_1d",
                "headerName": "1d Change",
                "cellDataType": "number",
                "formatterFn": "percent",
                "renderFn": "greenRed"
              }
            ]
          }
        }
      },
      "chains_chart": {
        "name": "TVL by Chain",
        "description": "Plotly bar chart of chain TVL.",
        "endpoint": "/chains-chart",
        "type": "chart",
        "w": 20,
        "h": 9,
        "params": [
          {
            "paramName": "chain",
            "type": "text",
            "label": "Chain",
            "value": "Ethereum",
            "description": "Chain the deck is focused on."
          }
        ],
        "data": {
          "raw": true
        }
      }
    },
    "apps_json": [
      {
        "name": "Chain Deck",
        "tabs": {
          "table": {
            "id": "table",
            "name": "Table",
            "layout": [
              {
                "i": "chains_table",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          "trend": {
            "id": "trend",
            "name": "Trend",
            "layout": [
              {
                "i": "chains_chart",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ],
            "groups": [
              {
                "name": "Chain Sync",
                "type": "param",
                "paramName": "chain",
                "widgetIds": [
                  "chains_table",
                  "chains_chart"
                ]
              }
            ]
          }
        }
      }
    ]
  }
}
